/*
 * disk_$validate_pv_label - read and sanity-check a physical volume label
 *
 * Original address: 0x00E6C21A (Ghidra disk_$validate_pv_label; module-local,
 * no SAU2 map symbol)
 * Size: 156 bytes (0x00E6C21A .. 0x00E6C2B5), constant to 0x00E6C2BB
 * Generated by: Claude Opus 5.5
 *
 * Callers: DISK_$PV_MOUNT_INTERNAL (0x00E6C408, 0x00E6C614).
 *
 * Frame (link.w A6,-0x14; D2-D3/A2-A3 saved):
 *   (0x08,A6) vol_idx  word
 *   (0x0A,A6) status   (A2)
 * Result in A0: the label buffer, NIL when the read failed.
 *
 * Blocks:
 *   0x00E6C226-0x00E6C24C  label = DISK_$GET_BLOCK(vol_idx, 0, &PV_LABEL_$UID,
 *                          0, 0, 0, status); an error returns NIL
 *   0x00E6C24E-0x00E6C264  num_parts > 1 (unsigned) and interleave not in
 *                          the set 0x37 = {0, 1, 2, 4, 5}: invalid
 *   0x00E6C266-0x00E6C282  version > 1 (unsigned) or the six bytes at +2
 *                          not "APOLLO": invalid
 *   0x00E6C284-0x00E6C2A2  num_parts not 8, 4, 2, 0 or 1: invalid
 *   0x00E6C2A4             *status = status_$invalid_physical_volume_label
 *
 * Quirks reproduced:
 *   - The label buffer is returned (still held) on the invalid path too.
 *   - The interleave set test is `btst.l D2,D3`: a bit number taken
 *     modulo 32.
 */

#include "disk/disk_internal.h"

/* Legal interleave modes for a striped set (`moveq #0x37,D3` 0x00E6C25C) */
#define DISK_PV_INTERLEAVE_SET  0x37

/* 0x00E6C2B6: the label signature, `lea (0x44,PC),A3` at 0x00E6C270 */
static const char disk_$pv_label_apollo[6] = { 'A', 'P', 'O', 'L', 'L', 'O' };

disk_$pv_label_t *disk_$validate_pv_label(int16_t vol_idx, status_$t *status)
{
    disk_$pv_label_t *label;            /* D0 */
    int8_t            bad;              /* D1b */
    int               i;

    /* 0x00E6C226-0x00E6C24C */
    label = (disk_$pv_label_t *)DISK_$GET_BLOCK(vol_idx, 0, &PV_LABEL_$UID,
                                                0, 0, 0, status);
    if (*status != status_$ok) {
        return NULL;
    }

    /* 0x00E6C24E-0x00E6C264: shi / btst / seq / and.b / bmi */
    if (label->num_parts > 1 &&
        ((DISK_PV_INTERLEAVE_SET >> (label->interleave & 31)) & 1) == 0) {
        goto invalid;
    }

    /* 0x00E6C266-0x00E6C282: shi, then cmpm.b / dbne over six bytes */
    bad = ((uint16_t)label->version > 1) ? (int8_t)0xFF : 0;
    for (i = 0; i < 6; i++) {
        if (label->apollo[i] != disk_$pv_label_apollo[i]) {
            bad = (int8_t)0xFF;
            break;
        }
    }
    if (bad < 0) {
        goto invalid;
    }

    /* 0x00E6C284-0x00E6C2A2 */
    switch (label->num_parts) {
    case 8:
    case 4:
    case 2:
    case 0:
    case 1:
        return label;
    default:
        break;
    }

invalid:
    /* 0x00E6C2A4 */
    *status = status_$invalid_physical_volume_label;
    return label;
}
